() => {
  // Pass this whole file as the `function` argument of browser_evaluate on a
  // Meta Ad Library results page. Anchors on visible text ("Library ID"),
  // never on Facebook's obfuscated class names. Returns one record per card
  // currently rendered; call again after scrolling and de-dupe by library_id.
  const ID_RE = /Library ID:?\s*(\d+)/;
  const countIds = el => (el.innerText.match(/Library ID:?\s*\d+/g) || []).length;
  const clean = s => s.replace(/[​ ]/g, ' ').trim();
  const leaves = [...document.querySelectorAll('span, div')]
    .filter(e => e.childElementCount === 0 && ID_RE.test(e.textContent.trim()));

  const months = { jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11 };
  const parseDate = s => {
    if (!s) return null;
    let m = s.match(/(\d{1,2}) (\w{3})\w* (\d{4})/);              // 28 Apr 2026
    if (m) return new Date(+m[3], months[m[2].toLowerCase()], +m[1]);
    m = s.match(/(\w{3})\w* (\d{1,2}),? (\d{4})/);                 // Apr 28, 2026
    if (m) return new Date(+m[3], months[m[1].toLowerCase()], +m[2]);
    return null;
  };

  const seen = new Set();
  const out = [];
  for (const leaf of leaves) {
    let card = leaf;
    while (card.parentElement && countIds(card.parentElement) === 1) card = card.parentElement;
    const text = card.innerText;
    const library_id = (text.match(ID_RE) || [])[1];
    if (!library_id || seen.has(library_id)) continue;
    seen.add(library_id);

    const lines = text.split('\n').map(clean).filter(Boolean);
    const startedRaw = (text.match(/Started running on ([^\n·]+)/) || [])[1] || null;
    const started = parseDate(startedRaw);
    const days_running = started ? Math.max(0, Math.round((Date.now() - started) / 86400000)) : null;
    const versionsMatch = text.match(/(\d+) ads use this creative and text/);
    const versions_count = versionsMatch ? +versionsMatch[1] : (/multiple versions/i.test(text) ? 'multiple' : 1);

    // Body = everything after "Sponsored" (advertiser line sits just before it).
    const sIdx = lines.findIndex(l => l === 'Sponsored');
    const page_name = sIdx > 0 ? lines[sIdx - 1] : null;
    let body = sIdx >= 0 ? lines.slice(sIdx + 1) : [];
    body = body.filter(l => !/^\d+:\d{2} \/ \d+:\d{2}$/.test(l)); // video timer
    const CTAS = /^(Shop now|Learn more|Sign up|Order now|Buy now|Book now|Download|Install now|Get offer|Get quote|Contact us|Send message|Subscribe|Apply now|Watch more|Send WhatsApp message|Call now|See menu|Get directions|Play game|Use app|Listen now|Donate now|Request time|Get started)$/i;
    const cta_button = body.length && CTAS.test(body[body.length - 1]) ? body.pop() : null;
    const domIdx = body.findIndex(l => /^[A-Z0-9-]+(\.[A-Z0-9-]+)+(\/\S*)?$/.test(l));
    const landing_domain = domIdx >= 0 ? body[domIdx].toLowerCase() : null;
    const primary_text = (domIdx >= 0 ? body.slice(0, domIdx) : body).join('\n') || null;
    const after = domIdx >= 0 ? body.slice(domIdx + 1) : [];
    const headline = after[0] || null;
    const link_description = after.slice(1).join(' ') || null;

    const videos = [...card.querySelectorAll('video')].map(v => ({
      src: v.currentSrc || v.src || null,
      poster: v.poster || null,
      duration_s: isFinite(v.duration) ? Math.round(v.duration) : null,
    }));
    // Skip the advertiser avatar (small, ~60px) — keep creative-sized images.
    const images = [...card.querySelectorAll('img')]
      .filter(i => (i.naturalWidth || i.width) >= 150)
      .map(i => i.currentSrc || i.src)
      .filter(src => src && !videos.some(v => v.poster === src));
    const isCarousel = images.length > 1 && !videos.length;

    const platformIcons = (() => {
      const lbl = [...card.querySelectorAll('span, div')].find(e => e.childElementCount === 0 && e.textContent.trim() === 'Platforms');
      if (!lbl) return null;
      const row = lbl.parentElement && lbl.parentElement.parentElement;
      return row ? row.querySelectorAll('[style*="mask-image"]').length : null;
    })();

    out.push({
      library_id,
      status: /\bActive\b/.test(lines.slice(0, 4).join(' ')) ? 'active' : 'inactive',
      started_running: startedRaw,
      days_running,
      platforms: platformIcons !== null ? `${platformIcons} platform icon(s) — names not exposed as text` : null,
      versions_count,
      format: videos.length ? 'video' : (isCarousel ? 'carousel' : (images.length ? 'image' : 'unknown')),
      page_name,
      // "<creator> with <Brand>" = partnership / creator (UGC) ad
      is_partnership: !!(page_name && / with /.test(page_name)),
      primary_text,
      headline,
      link_description,
      cta_button,
      landing_domain,
      image_urls: images,
      video_urls: videos,
      has_see_ad_details: /See (ad|summary) details/.test(text),
    });
  }
  return { url: location.href, card_count: out.length, cards: out };
}

"""Probe a downloaded ad video, pull hook + scene-change frames, and transcribe if possible.

Usage:
    python tools/competitor_ad_agent/video_frames.py <video.mp4> <frames_dir> [--transcript <out.txt>]

Prints a JSON summary to stdout. Works without a system ffmpeg by falling back
to the binary bundled with the `imageio-ffmpeg` pip package.
"""

import json
import re
import shutil
import subprocess
import sys
from pathlib import Path

HOOK_TIMES = [0, 0.5, 1.0, 1.5, 2.0, 2.5, 3.0]
MAX_SCENE_FRAMES = 12
SCENE_THRESHOLD = 0.3


def find_ffmpeg():
    exe = shutil.which("ffmpeg")
    if exe:
        return exe
    try:
        import imageio_ffmpeg
        return imageio_ffmpeg.get_ffmpeg_exe()
    except ImportError:
        return None


def run(cmd):
    return subprocess.run(cmd, capture_output=True, text=True, encoding="utf-8", errors="replace")


def probe(ffmpeg, video):
    # `ffmpeg -i` with no output exits non-zero but prints stream info to stderr.
    err = run([ffmpeg, "-hide_banner", "-i", str(video)]).stderr
    info = {"duration_s": None, "width": None, "height": None, "aspect_ratio": None, "has_audio": "Audio:" in err}
    m = re.search(r"Duration: (\d+):(\d+):(\d+(?:\.\d+)?)", err)
    if m:
        info["duration_s"] = round(int(m[1]) * 3600 + int(m[2]) * 60 + float(m[3]), 2)
    m = re.search(r"Video:.*?(\d{2,5})x(\d{2,5})", err)
    if m:
        w, h = int(m[1]), int(m[2])
        info.update(width=w, height=h, aspect_ratio=nearest_ratio(w, h))
    return info


def nearest_ratio(w, h):
    ratios = {"9:16": 9 / 16, "4:5": 4 / 5, "1:1": 1.0, "16:9": 16 / 9, "2:3": 2 / 3, "3:4": 3 / 4}
    r = w / h
    return min(ratios, key=lambda k: abs(ratios[k] - r))


def hook_frames(ffmpeg, video, out_dir, duration):
    saved = []
    for t in HOOK_TIMES:
        if duration is not None and t >= duration:
            break
        name = f"hook_{t:04.1f}s.jpg".replace(".", "_", 1)
        dest = out_dir / name
        run([ffmpeg, "-hide_banner", "-loglevel", "error", "-y", "-ss", str(t), "-i", str(video),
             "-frames:v", "1", "-q:v", "3", str(dest)])
        if dest.exists():
            saved.append({"t": t, "file": dest.name})
    return saved


def scene_frames(ffmpeg, video, out_dir):
    pattern = out_dir / "scene_%02d.jpg"
    res = run([ffmpeg, "-hide_banner", "-y", "-ss", "3", "-i", str(video),
               "-vf", f"select='gt(scene,{SCENE_THRESHOLD})',showinfo", "-vsync", "vfr",
               "-frames:v", str(MAX_SCENE_FRAMES), "-q:v", "3", str(pattern)])
    times = [round(float(t) + 3, 2) for t in re.findall(r"pts_time:([\d.]+)", res.stderr)]
    files = sorted(out_dir.glob("scene_*.jpg"))
    return [{"t": times[i] if i < len(times) else None, "file": f.name} for i, f in enumerate(files)]


def transcribe(video, out_path):
    try:
        from faster_whisper import WhisperModel
        model = WhisperModel("small", compute_type="int8")
        segments, _ = model.transcribe(str(video))
        lines = [f"[{s.start:05.1f}-{s.end:05.1f}] {s.text.strip()}" for s in segments]
        engine = "faster-whisper"
    except ImportError:
        try:
            import whisper
            result = whisper.load_model("small").transcribe(str(video))
            lines = [f"[{s['start']:05.1f}-{s['end']:05.1f}] {s['text'].strip()}" for s in result["segments"]]
            engine = "openai-whisper"
        except ImportError:
            return {"status": "no transcript", "reason": "no whisper package installed"}
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines) or "(no speech detected)", encoding="utf-8")
    return {"status": "ok", "engine": engine, "file": str(out_path)}


def main():
    args = sys.argv[1:]
    if len(args) < 2:
        print(__doc__)
        sys.exit(2)
    video, out_dir = Path(args[0]), Path(args[1])
    transcript = Path(args[args.index("--transcript") + 1]) if "--transcript" in args else None

    ffmpeg = find_ffmpeg()
    if not ffmpeg:
        print(json.dumps({"error": "ffmpeg not found; pip install imageio-ffmpeg"}))
        sys.exit(1)

    out_dir.mkdir(parents=True, exist_ok=True)
    info = probe(ffmpeg, video)
    summary = {
        "video": str(video),
        **info,
        "hook_frames": hook_frames(ffmpeg, video, out_dir, info["duration_s"]),
        "scene_frames": scene_frames(ffmpeg, video, out_dir),
        "frames_dir": str(out_dir),
    }
    if transcript:
        summary["transcript"] = transcribe(video, transcript) if info["has_audio"] else {"status": "no audio track"}
    (out_dir / "meta.json").write_text(json.dumps(summary, indent=2), encoding="utf-8")
    print(json.dumps(summary, indent=2))


if __name__ == "__main__":
    main()

